def _compute_extract_dir_static(path: str) -> str:
    lp = path.lower()
    for ext in sorted(SUPPORTED_FORMATS.keys(), key=len, reverse=True):
        if lp.endswith(ext):
            return path[:-len(ext)] + "_extracted"
    return os.path.splitext(path)[0] + "_extracted"

def _get_extension_static(path: str) -> str:
    lp = path.lower()
    exts = list(SUPPORTED_FORMATS.keys()) + list(SPECIAL_EXTENSIONS)
    exts = [e for e in exts if e != ".gz"]
    exts.sort(key=len, reverse=True)
    for ext in exts:
        if lp.endswith(ext):
            return ext
    if lp.endswith(".gz"):
        return ".gz"
    if lp.endswith(".tar.gz"):
        return ".tar.gz"
    return os.path.splitext(path)[1].lower()

def _scan_and_count_static(
    directory: str,
) -> Tuple[Set[str], List[str], List[str], List[str], List[str], Dict[str, int]]:
    """Один os.walk — сканирование файлов + подсчёт расширений."""
    exts: Set[str] = set()
    classes: List[str] = []
    specials: List[str] = []
    kotlins: List[str] = []
    third_party: List[str] = []
    ext_counts: Dict[str, int] = {}

    for root, _, files in os.walk(directory):
        if "__MACOSX" in root:
            continue
        for f in files:
            if f.startswith("._"):
                continue
            full = os.path.join(root, f)
            rel = os.path.relpath(full, directory)
            le = f.lower()

            if le.endswith(".kt") or le.endswith(".kts"):
                kotlins.append(rel)
            if le.endswith(CLASS_EXTENSION):
                classes.append(rel)

            ext = ".tar.gz" if le.endswith(".tar.gz") else os.path.splitext(f)[1].lower()
            if ext in SPECIAL_EXTENSIONS:
                specials.append(rel)
            if ext in THIRD_PARTY_ARCHIVE_EXTS:
                third_party.append(rel)
            if ext:
                exts.add(ext)
                ext_counts[ext] = ext_counts.get(ext, 0) + 1

    return exts, classes, specials, kotlins, third_party, ext_counts

def _scan_disk_static(directory: str) -> Tuple[Set[str], List[str], List[str], List[str], List[str]]:
    exts, classes, specials, kotlins, third_party, _ = _scan_and_count_static(directory)
    return exts, classes, specials, kotlins, third_party

def _count_extensions_static(directory: str) -> Dict[str, int]:
    """Count files per extension across the directory tree."""
    _, _, _, _, _, ext_counts = _scan_and_count_static(directory)
    return ext_counts

def _find_7z_console_static() -> Optional[str]:
    """Find 7z.exe without class instance (for static/CLI use)."""
    p = os.environ.get("PAXO_7Z_PATH")
    if p and os.path.isfile(p):
        return os.path.normpath(p)
    try:
        base = os.path.dirname(os.path.abspath(__file__))
    except Exception:
        base = os.getcwd()
    candidates: List[str] = []
    for n in ("7z.exe", "7za.exe", "7zr.exe", "7z"):
        candidates.append(os.path.join(base, "bin", n))
    for n in ("7z.exe", "7za.exe", "7zr.exe", "7z"):
        q = shutil.which(n)
        if q:
            candidates.append(q)
    if sys.platform.startswith("win"):
        for prog in (os.environ.get("ProgramFiles", ""),
                     os.environ.get("ProgramFiles(x86)", "")):
            if not prog:
                continue
            for n in ("7z.exe", "7za.exe"):
                candidates.append(os.path.join(prog, "7-Zip", n))
        try:
            import winreg
            for hive in (winreg.HKEY_LOCAL_MACHINE, winreg.HKEY_CURRENT_USER):
                for subkey in (r"SOFTWARE\7-Zip", r"SOFTWARE\7-Zip-Zstandard"):
                    try:
                        with winreg.OpenKey(hive, subkey) as key:
                            path7z, _ = winreg.QueryValueEx(key, "Path")
                            if path7z:
                                candidates.append(os.path.join(path7z, "7z.exe"))
                    except Exception:
                        pass
        except Exception:
            pass
        home = os.environ.get("USERPROFILE", "")
        for d in [
            os.path.join(os.environ.get("ChocolateyInstall", r"C:\ProgramData\chocolatey"), "bin"),
            os.path.join(home, "scoop", "apps", "7zip", "current"),
            r"C:\7-Zip", r"D:\7-Zip",
        ]:
            for n in ("7z.exe", "7za.exe"):
                candidates.append(os.path.join(d, n))
    for c in candidates:
        if c and os.path.isfile(c):
            return os.path.normpath(c)
    return None

