def _parse_version_tuple(version: str) -> Tuple:
    """Parse a version string into a tuple of ints for comparison."""
    parts: List[int] = []
    for p in re.split(r"[.\-_]", version):
        m = re.match(r"(\d+)", p)
        if m:
            parts.append(int(m.group(1)))
    return tuple(parts) if parts else (0,)

def _version_in_range(version: str, range_start: str, range_end: str) -> bool:
    """Check if version is within [range_start, range_end] inclusive."""
    try:
        v = _parse_version_tuple(version)
        lo = _parse_version_tuple(range_start)
        hi = _parse_version_tuple(range_end)
        return lo <= v <= hi
    except Exception:
        return False

def _check_known_cves(dependencies: Dict) -> List[Dict]:
    """Check extracted dependencies against the known CVE database."""
    results: List[Dict] = []
    seen: Set[Tuple[str, str, str]] = set()

    all_deps: List[Tuple[Dict, str]] = []
    for lang in ("java", "js", "python"):
        for dep in dependencies.get(lang, []):
            all_deps.append((dep, lang))

    for dep, _lang in all_deps:
        artifact = dep.get("artifact", "")
        version = dep.get("version", "").lstrip("^~>=<!")
        source = dep.get("source", "")
        if not version or not artifact:
            continue

        for pattern, v_start, v_end, cve_id, severity, description in _KNOWN_CVES:
            if pattern.lower() not in artifact.lower():
                continue
            # More precise: artifact should end with the pattern or equal it
            art_lower = artifact.lower()
            pat_lower = pattern.lower()
            if art_lower != pat_lower and not art_lower.endswith(pat_lower):
                continue

            if _version_in_range(version, v_start, v_end):
                key = (artifact, version, cve_id)
                if key not in seen:
                    seen.add(key)
                    results.append({
                        "artifact": artifact,
                        "version": version,
                        "cve": cve_id,
                        "severity": severity,
                        "description": description,
                        "source_file": source,
                    })

    return results

