def _build_import_graph_full(directory: str) -> Dict:
    """Build a full import graph from .java/.kt source files."""
    # Collect source files
    sources: List[str] = []
    try:
        for root, _dirs, files in os.walk(directory):
            for fname in files:
                if fname.endswith((".java", ".kt")):
                    sources.append(os.path.relpath(os.path.join(root, fname), directory))
    except Exception:
        pass

    packages: Set[str] = set()
    edges: Set[Tuple[str, str]] = set()
    file_packages: Dict[str, str] = {}  # file -> package

    for src in sources:
        full = os.path.join(directory, src)
        try:
            with open(full, "r", encoding="utf-8", errors="replace") as f:
                content = _read_limited(f)
        except Exception:
            continue

        # Extract package
        pkg_match = _PACKAGE_DECL_RE.search(content)
        pkg = pkg_match.group(1) if pkg_match else "(default)"
        packages.add(pkg)
        file_packages[src] = pkg

        # Extract imports
        for m in _IMPORT_DECL_RE.finditer(content):
            imp = m.group(1)
            # Skip stdlib/third-party
            if any(imp.startswith(p) for p in _IMPORT_GRAPH_STDLIB_PREFIXES):
                continue
            # Extract package from import (remove class name)
            parts = imp.rsplit(".", 1)
            if len(parts) == 2:
                imp_pkg = parts[0]
                # Only include if it looks like a project package (lowercase segments)
                if imp_pkg and imp_pkg != pkg:
                    edges.add((pkg, imp_pkg))
                    packages.add(imp_pkg)

    # Filter to only project-internal packages (both ends must be known)
    internal_edges: Set[Tuple[str, str]] = set()
    for frm, to in edges:
        if frm in packages and to in packages:
            internal_edges.add((frm, to))

    # Build adjacency for cluster detection
    adj: Dict[str, Set[str]] = defaultdict(set)
    incoming: Dict[str, Set[str]] = defaultdict(set)
    for frm, to in internal_edges:
        adj[frm].add(to)
        incoming[to].add(frm)

    # Find isolated packages (no incoming edges from non-test packages)
    isolated: List[str] = []
    for pkg in packages:
        callers = incoming.get(pkg, set())
        non_test_callers = {c for c in callers if "test" not in c.lower()}
        if not non_test_callers and pkg in adj:
            isolated.append(pkg)

    # Find connected components (clusters)
    visited: Set[str] = set()
    clusters: List[List[str]] = []

    # Build undirected adjacency
    undirected: Dict[str, Set[str]] = defaultdict(set)
    for frm, to in internal_edges:
        undirected[frm].add(to)
        undirected[to].add(frm)

    for pkg in sorted(packages):
        if pkg in visited:
            continue
        # BFS
        cluster: List[str] = []
        queue = [pkg]
        while queue:
            node = queue.pop(0)
            if node in visited:
                continue
            visited.add(node)
            cluster.append(node)
            for neighbor in sorted(undirected.get(node, set())):
                if neighbor not in visited:
                    queue.append(neighbor)
        if cluster:
            clusters.append(sorted(cluster))

    return {
        "packages": sorted(packages),
        "edges": sorted(internal_edges),
        "isolated": sorted(isolated),
        "clusters": clusters,
        "stats": {
            "total_packages": len(packages),
            "total_edges": len(internal_edges),
        },
    }

