class _FileTreeCache:
    """Кэш результата os.walk() для ускорения анализа."""
    __slots__ = ("directory", "entries", "_rel_cache", "_stat_cache")

    def __init__(self, directory: str) -> None:
        self.directory = directory
        # entries: list of (root, dirs, files)
        self.entries: List[Tuple[str, List[str], List[str]]] = []
        self._rel_cache: Dict[str, str] = {}
        self._stat_cache: Dict[str, os.stat_result] = {}
        for root, dirs, files in os.walk(directory):
            self.entries.append((root, list(dirs), list(files)))

    def walk(self):
        """Возвращает итератор как os.walk(), но из кэша."""
        return iter(self.entries)

    def rel_path(self, full_path: str) -> str:
        """os.path.relpath от directory, с кэшем."""
        r = self._rel_cache.get(full_path)
        if r is None:
            r = os.path.relpath(full_path, self.directory).replace("\\", "/")
            self._rel_cache[full_path] = r
        return r

    def stat(self, full_path: str) -> Optional[os.stat_result]:
        """os.stat с кэшем. Возвращает None при ошибке."""
        s = self._stat_cache.get(full_path)
        if s is not None:
            return s
        try:
            s = os.stat(full_path)
            self._stat_cache[full_path] = s
            return s
        except OSError:
            return None

def _build_file_tree_cache(directory: str) -> _FileTreeCache:
    """Создаёт кэш файлового дерева для переиспользования в sub-checks."""
    return _FileTreeCache(directory)

def _check_missing_imports(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Parse import statements and check if referenced classes exist in archive."""
    findings: List[Dict[str, str]] = []

    # Build index: package-qualified name -> file exists
    _walk = ftc.walk() if ftc else os.walk(directory)
    existing: Set[str] = set()
    for root, _, files in _walk:
        for f in files:
            full_f = os.path.join(root, f)
            rel = ftc.rel_path(full_f) if ftc else os.path.relpath(full_f, directory).replace("\\", "/")
            # Store as dotted package path without extension
            no_ext = os.path.splitext(rel)[0]
            existing.add(no_ext.replace("/", "."))

    # Also build set of existing packages (directories)
    _walk2 = ftc.walk() if ftc else os.walk(directory)
    existing_dirs: Set[str] = set()
    for root, dirs, _ in _walk2:
        for d in dirs:
            full_d = os.path.join(root, d)
            rel = ftc.rel_path(full_d) if ftc else os.path.relpath(full_d, directory).replace("\\", "/")
            existing_dirs.add(rel.replace("/", "."))

    # Patterns for different languages
    java_import = re.compile(r'^\s*import\s+(?:static\s+)?([a-zA-Z_][\w.]*\.\w+)\s*;', re.MULTILINE)
    kt_import = re.compile(r'^\s*import\s+([a-zA-Z_][\w.]*\.\w+)', re.MULTILINE)
    py_import_from = re.compile(r'^\s*from\s+([\w.]+)\s+import\s+', re.MULTILINE)
    py_import = re.compile(r'^\s*import\s+([\w.]+)', re.MULTILINE)

    missing_by_file: Dict[str, List[str]] = defaultdict(list)

    _walk3 = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk3:
        if "__MACOSX" in root or "__pycache__" in root:
            continue
        for f in files:
            full = os.path.join(root, f)
            rel = ftc.rel_path(full) if ftc else os.path.relpath(full, directory).replace("\\", "/")
            le = f.lower()

            try:
                if le.endswith((".java", ".kt", ".kts")):
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(65536)
                    pat = kt_import if le.endswith((".kt", ".kts")) else java_import
                    for m in pat.finditer(content):
                        imp = m.group(1)
                        if any(imp.startswith(p) for p in _STDLIB_PREFIXES):
                            continue
                        # Check if class or package exists
                        if imp not in existing:
                            # Try parent package (wildcard import)
                            parent = imp.rsplit(".", 1)[0] if "." in imp else imp
                            if parent not in existing_dirs and parent not in existing:
                                missing_by_file[rel].append(imp)
                elif le.endswith(".py"):
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(65536)
                    for m in py_import_from.finditer(content):
                        mod = m.group(1)
                        if mod.startswith(("os", "sys", "re", "json", "typing",
                                           "collections", "functools", "pathlib",
                                           "datetime", "logging", "unittest",
                                           "abc", "io", "math", "hashlib",
                                           "subprocess", "shutil", "glob",
                                           "dataclasses", "enum", "copy")):
                            continue
                        if mod not in existing and mod not in existing_dirs:
                            missing_by_file[rel].append(mod)
            except Exception:
                continue

    # Deduplicate and report
    all_missing: Dict[str, int] = defaultdict(int)
    for rel, imports in missing_by_file.items():
        for imp in imports:
            all_missing[imp] += 1

    for imp, cnt in sorted(all_missing.items(), key=lambda x: -x[1]):
        findings.append({
            "detail": f"{imp} (ссылок: {cnt})",
            "severity": "high" if cnt >= 3 else "medium",
        })

    return findings

def _check_module_declarations(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Check if modules declared in build files actually exist."""
    findings: List[Dict[str, str]] = []

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        for f in files:
            full = os.path.join(root, f)
            _rel_full = ftc.rel_path(full) if ftc else os.path.relpath(full, directory).replace("\\", "/")
            rel_dir = os.path.dirname(_rel_full)

            try:
                if f in ("settings.gradle.kts", "settings.gradle"):
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(32768)
                    # include(":module1", ":module2") or include ":module1"
                    for m in re.finditer(r'include\s*\(?["\'][:"]?([^"\']+)["\']', content):
                        mod_name = m.group(1).lstrip(":").replace(":", "/")
                        mod_path = os.path.join(root, rel_dir, mod_name) if rel_dir else os.path.join(root, mod_name)
                        # Also check relative to the settings.gradle location
                        settings_dir = os.path.dirname(full)
                        mod_path2 = os.path.join(settings_dir, mod_name)
                        if not os.path.isdir(mod_path) and not os.path.isdir(mod_path2):
                            findings.append({
                                "detail": f"Модуль '{mod_name}' заявлен в {_rel_full} но отсутствует",
                                "severity": "critical",
                            })

                elif f == "pom.xml":
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(32768)
                    for m in re.finditer(r'<module>\s*([^<]+?)\s*</module>', content):
                        mod_name = m.group(1)
                        mod_path = os.path.join(os.path.dirname(full), mod_name)
                        if not os.path.isdir(mod_path):
                            findings.append({
                                "detail": f"Модуль '{mod_name}' заявлен в {_rel_full} но отсутствует",
                                "severity": "critical",
                            })

                elif f == "package.json":
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(32768)
                    try:
                        import json
                        pkg = json.loads(content)
                        workspaces = pkg.get("workspaces", [])
                        if isinstance(workspaces, dict):
                            workspaces = workspaces.get("packages", [])
                        for ws in workspaces:
                            if "*" in ws:
                                continue
                            ws_path = os.path.join(os.path.dirname(full), ws)
                            if not os.path.isdir(ws_path):
                                findings.append({
                                    "detail": f"Workspace '{ws}' заявлен в {_rel_full} но отсутствует",
                                    "severity": "critical",
                                })
                    except Exception:
                        pass
            except Exception:
                continue

    return findings

def _check_stub_files(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect empty or stub source files (<50 bytes or only declarations)."""
    findings: List[Dict[str, str]] = []
    source_exts = {".java", ".kt", ".kts", ".py", ".js", ".ts", ".go", ".rs",
                   ".rb", ".php", ".cs", ".swift", ".scala"}
    stub_pattern = re.compile(
        r'^\s*(package\s+\S+[;\s]*)?\s*'
        r'(import\s+[^;]+;\s*)*'
        r'((/\*.*?\*/|//[^\n]*)\s*)*'
        r'((public|private|internal|open|abstract|sealed|data|final)\s+)*'
        r'(class|interface|object|enum|struct)\s+\w+\s*'
        r'(\([^)]*\))?\s*'
        r'(:\s*\w+(\([^)]*\))?\s*(,\s*\w+(\([^)]*\))?\s*)*)?\s*'
        r'\{?\s*\}?\s*$',
        re.DOTALL
    )

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        if "__MACOSX" in root:
            continue
        for f in files:
            ext = os.path.splitext(f)[1].lower()
            if ext not in source_exts:
                continue
            full = os.path.join(root, f)
            rel = ftc.rel_path(full) if ftc else os.path.relpath(full, directory).replace("\\", "/")
            try:
                size = os.path.getsize(full)
                if size == 0:
                    findings.append({"detail": f"{rel} (пустой файл, 0 байт)", "severity": "high"})
                elif size < 50:
                    findings.append({"detail": f"{rel} ({size} байт)", "severity": "high"})
                elif size < 300:
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(300)
                    stripped = content.strip()
                    if stub_pattern.match(stripped):
                        findings.append({"detail": f"{rel} (заглушка, {size} байт)", "severity": "medium"})
            except Exception:
                continue

    return findings

def _check_missing_packages(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect package declarations that don't match directory structure."""
    findings: List[Dict[str, str]] = []
    pkg_decl = re.compile(r'^\s*package\s+([\w.]+)', re.MULTILINE)
    seen_mismatches: Set[str] = set()

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        if "__MACOSX" in root:
            continue
        for f in files:
            le = f.lower()
            if not le.endswith((".java", ".kt", ".kts")):
                continue
            full = os.path.join(root, f)
            rel = ftc.rel_path(full) if ftc else os.path.relpath(full, directory).replace("\\", "/")
            try:
                with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                    head = fh.read(1024)
                m = pkg_decl.search(head)
                if not m:
                    continue
                declared_pkg = m.group(1)
                # Check dir path contains the package path
                expected_path = declared_pkg.replace(".", "/")
                actual_dir = os.path.dirname(rel)
                if expected_path not in actual_dir and declared_pkg not in seen_mismatches:
                    seen_mismatches.add(declared_pkg)
                    findings.append({
                        "detail": f"Пакет '{declared_pkg}' объявлен в {rel}, но путь '{actual_dir}' не соответствует",
                        "severity": "medium",
                    })
            except Exception:
                continue

    return findings

def _check_broken_inheritance(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect extends/implements referencing classes not in archive."""
    findings: List[Dict[str, str]] = []

    # Build set of all known class names in archive
    known_classes: Set[str] = set()
    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        for f in files:
            if f.lower().endswith((".java", ".kt", ".kts", ".class")):
                stem = os.path.splitext(f)[0]
                known_classes.add(stem)

    extends_re = re.compile(r'\b(?:extends|implements)\s+([\w,\s]+?)[\s{]', re.MULTILINE)
    kt_inherits_re = re.compile(
        r'(?:class|interface|object)\s+\w+(?:\s*<[^>]*>)?'
        r'(?:\s*\([^)]*\))?\s*:\s*([\w\s,<>()]+?)(?:\s*\{|$)',
        re.MULTILINE
    )
    stdlib_classes = {
        # Java/Kotlin stdlib
        "Object", "String", "Exception", "RuntimeException", "Throwable",
        "Serializable", "Comparable", "Cloneable", "Runnable", "Callable",
        "Iterable", "Iterator", "Collection", "List", "Map", "Set",
        "ArrayList", "HashMap", "HashSet", "LinkedList", "AbstractList",
        "Any", "Unit", "Nothing", "Annotation", "Enum", "Number",
        "CoroutineScope", "Flow", "StateFlow", "SharedFlow", "Channel",
        # Android
        "Application", "Activity", "Fragment", "Service", "BroadcastReceiver",
        "ViewModel", "LiveData", "MutableLiveData",
        "View", "ViewGroup", "RecyclerView", "Adapter",
        # Spring / common frameworks
        "CrudRepository", "JpaRepository", "PagingAndSortingRepository",
        "Repository", "RestController", "Controller", "Component",
        "Configuration", "Bean", "Autowired", "Value",
        "ResponseEntity", "RequestBody", "PathVariable",
        "WebMvcConfigurer", "WebSecurityConfigurerAdapter",
        "AbstractRoutingDataSource", "JdbcTemplate",
        "KLogging", "KotlinLogging",
        # Testing
        "TestCase", "TestSuite", "Specification",
        "AnnotationSpec", "BehaviorSpec", "FunSpec", "StringSpec",
        "FreeSpec", "WordSpec", "FeatureSpec", "DescribeSpec",
        "MockBean", "SpyBean",
    }
    missing: Dict[str, int] = defaultdict(int)

    _walk2 = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk2:
        if "__MACOSX" in root:
            continue
        for f in files:
            le = f.lower()
            if not le.endswith((".java", ".kt", ".kts")):
                continue
            full = os.path.join(root, f)
            try:
                with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                    content = fh.read(65536)

                refs: List[str] = []
                if le.endswith(".java"):
                    for m in extends_re.finditer(content):
                        for name in re.split(r'[,\s]+', m.group(1)):
                            name = name.strip().split("<")[0]
                            if name:
                                refs.append(name)
                else:
                    for m in kt_inherits_re.finditer(content):
                        for part in m.group(1).split(","):
                            name = part.strip().split("(")[0].split("<")[0].strip()
                            if name:
                                refs.append(name)

                for ref in refs:
                    if ref in stdlib_classes or ref in known_classes:
                        continue
                    if len(ref) < 2 or ref[0].islower():
                        continue
                    missing[ref] += 1
            except Exception:
                continue

    for cls, cnt in sorted(missing.items(), key=lambda x: -x[1]):
        sev = "high" if cnt >= 3 else "medium"
        findings.append({"detail": f"{cls} (ссылок: {cnt})", "severity": sev})

    return findings

def _check_numbering_gaps(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect gaps in numbered directories/files (v1, v3 but no v2)."""
    findings: List[Dict[str, str]] = []
    num_pattern = re.compile(r'^(.*?)(\d+)$')

    # Check top 3 levels
    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, dirs, _ in _walk:
        depth = root.replace(directory, "").count(os.sep)
        if depth > 3:
            if not ftc:
                dirs.clear()
            continue
        groups: Dict[str, List[int]] = defaultdict(list)
        for d in dirs:
            m = num_pattern.match(d)
            if m:
                prefix = m.group(1)
                num = int(m.group(2))
                groups[prefix].append(num)

        for prefix, nums in groups.items():
            if len(nums) < 2:
                continue
            nums.sort()
            for i in range(len(nums) - 1):
                if nums[i + 1] - nums[i] > 1:
                    rel = ftc.rel_path(root) if ftc else os.path.relpath(root, directory).replace("\\", "/")
                    missing_range = list(range(nums[i] + 1, nums[i + 1]))
                    missing_names = [f"{prefix}{n}" for n in missing_range[:5]]
                    findings.append({
                        "detail": f"В '{rel}/' пропущены: {', '.join(missing_names)}"
                                  f"{' ...' if len(missing_range) > 5 else ''}",
                        "severity": "low",
                    })

    return findings

def _check_missing_layers(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect missing architectural layers (e.g., has controller/ but no security/)."""
    findings: List[Dict[str, str]] = []

    all_layers_found: Set[str] = set()
    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, dirs, _ in _walk:
        for d in dirs:
            dl = d.lower()
            if dl in _KNOWN_LAYER_NAMES:
                all_layers_found.add(dl)

    if not all_layers_found:
        return findings

    # If project has business layers, check for critical ones
    has_business = bool(all_layers_found & {
        "controller", "controllers", "rest", "api", "endpoint", "endpoints",
        "service", "services", "usecase", "usecases",
    })

    if has_business:
        missing_critical = _CRITICAL_LAYERS - all_layers_found
        for layer in sorted(missing_critical):
            findings.append({
                "detail": f"Слой '{layer}/' отсутствует (есть: {', '.join(sorted(all_layers_found & {'controller','controllers','service','services','api','rest'}))})",
                "severity": "high",
            })

    return findings

def _check_dead_config_refs(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Check config files (application.yml/properties) for references to missing classes."""
    findings: List[Dict[str, str]] = []

    # Build class index
    known_classes: Set[str] = set()
    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        for f in files:
            if f.lower().endswith((".java", ".kt", ".kts", ".class")):
                full_f = os.path.join(root, f)
                rel = ftc.rel_path(full_f) if ftc else os.path.relpath(full_f, directory).replace("\\", "/")
                dotted = os.path.splitext(rel)[0].replace("/", ".")
                known_classes.add(dotted)
                # Also add just the class name
                known_classes.add(os.path.splitext(f)[0])

    class_ref_re = re.compile(r'[a-z]+(?:\.[a-z]+){2,}\.[A-Z]\w+')

    config_files = ("application.yml", "application.yaml", "application.properties",
                    "application-dev.yml", "application-prod.yml",
                    "bootstrap.yml", "bootstrap.yaml")

    _walk2 = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk2:
        for f in files:
            if f.lower() not in config_files:
                continue
            full = os.path.join(root, f)
            try:
                with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                    content = fh.read(32768)
                for m in class_ref_re.finditer(content):
                    ref = m.group(0)
                    if any(ref.startswith(p) for p in _STDLIB_PREFIXES):
                        continue
                    if ref not in known_classes:
                        simple = ref.rsplit(".", 1)[-1]
                        if simple not in known_classes:
                            _rel_cfg = ftc.rel_path(full) if ftc else os.path.relpath(full, directory).replace("\\", "/")
                            findings.append({
                                "detail": f"Класс '{ref}' в {_rel_cfg} не найден в архиве",
                                "severity": "medium",
                            })
            except Exception:
                continue

    return findings

def _check_missing_manifests(directory: str, ext_counts: Dict[str, int], ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Check if dependency manifests are missing for detected languages."""
    findings: List[Dict[str, str]] = []

    has_java = any(ext_counts.get(e, 0) > 0 for e in (".java", ".kt", ".class", ".scala"))
    has_python = ext_counts.get(".py", 0) > 0
    has_js = any(ext_counts.get(e, 0) > 0 for e in (".js", ".ts", ".jsx", ".tsx"))
    has_go = ext_counts.get(".go", 0) > 0
    has_ruby = ext_counts.get(".rb", 0) > 0
    has_php = ext_counts.get(".php", 0) > 0
    has_rust = ext_counts.get(".rs", 0) > 0
    has_cs = ext_counts.get(".cs", 0) > 0
    has_dart = ext_counts.get(".dart", 0) > 0
    has_swift = ext_counts.get(".swift", 0) > 0

    # Search for manifest files
    manifest_found: Set[str] = set()
    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        for f in files:
            fl = f.lower()
            manifest_found.add(fl)

    checks = [
        (has_java, {"pom.xml", "build.gradle", "build.gradle.kts"},
         "Java/Kotlin", "pom.xml / build.gradle"),
        (has_python, {"requirements.txt", "setup.py", "pyproject.toml", "pipfile", "setup.cfg"},
         "Python", "requirements.txt / pyproject.toml"),
        (has_js, {"package.json"},
         "JavaScript/TypeScript", "package.json"),
        (has_go, {"go.mod"},
         "Go", "go.mod"),
        (has_ruby, {"gemfile"},
         "Ruby", "Gemfile"),
        (has_php, {"composer.json"},
         "PHP", "composer.json"),
        (has_rust, {"cargo.toml"},
         "Rust", "Cargo.toml"),
        (has_cs, {".csproj", ".sln", "packages.config"},
         "C#", ".csproj / packages.config"),
        (has_dart, {"pubspec.yaml"},
         "Dart", "pubspec.yaml"),
        (has_swift, {"podfile", "package.swift"},
         "Swift", "Podfile / Package.swift"),
    ]

    for has_lang, required_files, lang_name, examples in checks:
        if has_lang and not (manifest_found & required_files):
            findings.append({
                "detail": f"Проект содержит {lang_name}, но нет {examples} — SCA/OSA не сможет обнаружить уязвимые зависимости",
                "severity": "critical",
            })

    return findings

def _check_missing_android_manifest(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Check if Android projects are missing AndroidManifest.xml."""
    findings: List[Dict[str, str]] = []

    has_android_signs = False
    has_manifest = False

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, dirs, files in _walk:
        for f in files:
            fl = f.lower()
            if fl == "androidmanifest.xml":
                has_manifest = True
            if fl.endswith(".dex") or fl == "r.java" or fl == "buildconfig.java":
                has_android_signs = True
        for d in dirs:
            if d == "res" and os.path.isdir(os.path.join(root, d, "layout")):
                has_android_signs = True
            if d == "com" or d == "android":
                pass  # not conclusive alone

    # Also check for Gradle Android plugin
    _walk2 = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk2:
        for f in files:
            if f in ("build.gradle", "build.gradle.kts"):
                try:
                    with open(os.path.join(root, f), "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(8192)
                    if "com.android" in content or "android {" in content:
                        has_android_signs = True
                except Exception:
                    pass

    if has_android_signs and not has_manifest:
        findings.append({
            "detail": "Android-проект без AndroidManifest.xml — скрыты permissions и компоненты",
            "severity": "critical",
        })

    return findings

def _check_date_anomalies(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect timestamp anomalies: all same date, sources older than build."""
    findings: List[Dict[str, str]] = []

    source_exts = {".java", ".kt", ".kts", ".py", ".js", ".ts", ".go", ".rs", ".scala"}
    build_exts = {".class", ".jar", ".war", ".dex"}

    timestamps: List[float] = []
    source_times: List[float] = []
    build_times: List[float] = []

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        if "__MACOSX" in root:
            continue
        for f in files:
            full = os.path.join(root, f)
            try:
                mtime = os.path.getmtime(full)
                timestamps.append(mtime)
                ext = os.path.splitext(f)[1].lower()
                if ext in source_exts:
                    source_times.append(mtime)
                elif ext in build_exts:
                    build_times.append(mtime)
            except Exception:
                continue

    if len(timestamps) > 10:
        # Check if >90% have the same timestamp (within 2 seconds)
        from collections import Counter
        rounded = [int(t / 2) * 2 for t in timestamps]
        counter = Counter(rounded)
        most_common_count = counter.most_common(1)[0][1]
        ratio = most_common_count / len(timestamps)
        if ratio > 0.9:
            findings.append({
                "detail": f"{most_common_count}/{len(timestamps)} файлов ({ratio:.0%}) имеют одинаковую дату — архив мог быть пересобран/подменён",
                "severity": "medium",
            })

    if source_times and build_times:
        avg_source = sum(source_times) / len(source_times)
        avg_build = sum(build_times) / len(build_times)
        diff_days = (avg_build - avg_source) / 86400
        if diff_days > 90:
            findings.append({
                "detail": f"Исходники старше билда в среднем на {int(diff_days)} дней — возможно предоставлена устаревшая версия кода",
                "severity": "high",
            })

    return findings

def _check_size_anomalies(directory: str, classes: List[str], kotlins: List[str], ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect size mismatches between source and compiled files (stub sources)."""
    findings: List[Dict[str, str]] = []

    # Build map: stem -> class file size (by package path)
    class_sizes: Dict[str, int] = {}
    for cp in classes:
        full = os.path.join(directory, cp)
        try:
            stem = os.path.splitext(os.path.basename(cp))[0].split("$")[0]
            pkg = _extract_package_path(cp)
            key = (os.path.dirname(pkg).replace("\\", "/") if pkg else os.path.dirname(cp).replace("\\", "/"), stem)
            size = os.path.getsize(full)
            # Keep the largest class file for this stem
            if key not in class_sizes or size > class_sizes[key]:
                class_sizes[key] = size
        except Exception:
            continue

    source_exts = (".java", ".kt", ".kts", ".scala")
    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        for f in files:
            ext = os.path.splitext(f)[1].lower()
            if ext not in source_exts:
                continue
            full = os.path.join(root, f)
            rel = os.path.relpath(full, directory)
            try:
                src_size = os.path.getsize(full)
                if src_size > 500:
                    continue  # Only flag suspiciously small sources
                stem = os.path.splitext(f)[0]
                pkg = _extract_package_path(rel)
                key = (os.path.dirname(pkg).replace("\\", "/") if pkg else os.path.dirname(rel).replace("\\", "/"), stem)

                class_size = class_sizes.get(key, 0)
                if class_size > 0 and src_size > 0 and class_size / src_size > 50:
                    findings.append({
                        "detail": f"{rel} ({src_size} Б) → .class ({class_size} Б, x{int(class_size/src_size)}) — исходник может быть заглушкой",
                        "severity": "high",
                    })
            except Exception:
                continue

    return findings

def _check_version_mismatches(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect version mismatches between build files."""
    findings: List[Dict[str, str]] = []
    versions_found: Dict[str, str] = {}

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        for f in files:
            full = os.path.join(root, f)
            rel = ftc.rel_path(full) if ftc else os.path.relpath(full, directory).replace("\\", "/")
            try:
                if f == "pom.xml":
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(8192)
                    m = re.search(r'<version>\s*([^<]+?)\s*</version>', content)
                    if m and "${" not in m.group(1):
                        versions_found[f"pom.xml ({rel})"] = m.group(1)
                elif f in ("build.gradle", "build.gradle.kts"):
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(8192)
                    m = re.search(r'version\s*[=:]\s*["\']([^"\']+)["\']', content)
                    if m:
                        versions_found[f"gradle ({rel})"] = m.group(1)
                elif f == "package.json":
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(8192)
                    import json
                    try:
                        pkg = json.loads(content)
                        v = pkg.get("version")
                        if v:
                            versions_found[f"package.json ({rel})"] = v
                    except Exception:
                        pass
                elif f == "gradle.properties":
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(4096)
                    m = re.search(r'version\s*=\s*(.+)', content)
                    if m:
                        versions_found[f"gradle.properties ({rel})"] = m.group(1).strip()
            except Exception:
                continue

    if len(versions_found) >= 2:
        unique_versions = set(versions_found.values())
        if len(unique_versions) > 1:
            details = "; ".join(f"{k}: {v}" for k, v in versions_found.items())
            findings.append({
                "detail": f"Разные версии: {details}",
                "severity": "medium",
            })

    return findings

def _check_nested_archives(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect archives inside the extracted archive, especially encrypted."""
    findings: List[Dict[str, str]] = []
    archive_exts = {".zip", ".7z", ".rar", ".tar", ".tar.gz", ".tgz",
                    ".tar.bz2", ".tar.xz", ".gz", ".bz2", ".xz"}

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        for f in files:
            ext = os.path.splitext(f)[1].lower()
            if f.lower().endswith(".tar.gz"):
                ext = ".tar.gz"
            if ext not in archive_exts:
                continue
            full = os.path.join(root, f)
            rel = ftc.rel_path(full) if ftc else os.path.relpath(full, directory).replace("\\", "/")
            size = 0
            try:
                size = os.path.getsize(full)
            except Exception:
                pass

            encrypted = False
            if ext == ".zip":
                try:
                    import zipfile
                    with zipfile.ZipFile(full, "r") as zf:
                        for info in zf.infolist():
                            if info.flag_bits & 0x1:
                                encrypted = True
                                break
                except Exception:
                    pass

            size_str = _format_size(size) if size else "?"
            if encrypted:
                findings.append({
                    "detail": f"{rel} ({size_str}) — зашифрованный архив! Содержимое скрыто",
                    "severity": "critical",
                })
            else:
                findings.append({
                    "detail": f"{rel} ({size_str}) — вложенный архив, содержимое не анализируется",
                    "severity": "medium",
                })

    return findings

def _check_renamed_extensions(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect files with wrong extensions (e.g. .java without class keyword)."""
    findings: List[Dict[str, str]] = []

    checks = {
        ".java": (re.compile(r'\b(class|interface|enum|@interface)\s+\w+'), "class/interface/enum"),
        ".kt": (re.compile(r'\b(fun|val|var|class|interface|object|typealias)\s+'), "fun/val/class/object"),
        ".kts": (re.compile(r'\b(fun|val|var|class|interface|object|plugins|dependencies|tasks)\s*'), "fun/val/plugins"),
        ".py": (re.compile(r'\b(def|class|import|from)\s+'), "def/class/import"),
    }

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        if "__MACOSX" in root:
            continue
        for f in files:
            ext = os.path.splitext(f)[1].lower()
            if ext not in checks:
                continue
            pattern, expected = checks[ext]
            full = os.path.join(root, f)
            try:
                size = os.path.getsize(full)
                if size < 10 or size > 1048576:
                    continue
                # Read enough to find keywords past long import blocks
                read_size = min(size, 16384)
                with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                    content = fh.read(read_size)
                if not pattern.search(content):
                    rel = ftc.rel_path(full) if ftc else os.path.relpath(full, directory).replace("\\", "/")
                    findings.append({
                        "detail": f"{rel} — файл {ext} не содержит '{expected}', возможно подмена",
                        "severity": "medium",
                    })
            except Exception:
                continue

    return findings

def _check_suspiciously_clean(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect code with zero comments/TODOs — may have been sanitized."""
    findings: List[Dict[str, str]] = []
    source_exts = {".java", ".kt", ".kts", ".py", ".js", ".ts", ".go", ".rs", ".scala"}

    total_lines = 0
    comment_lines = 0
    todo_count = 0
    file_count = 0
    comment_re = re.compile(r'^\s*(//|/\*|\*|#\s)', re.MULTILINE)
    todo_re = re.compile(r'\b(TODO|FIXME|HACK|XXX|WARN|DEPRECATED)\b', re.IGNORECASE)

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        if "__MACOSX" in root or "generated" in root.lower() or "build" in root.lower():
            continue
        for f in files:
            ext = os.path.splitext(f)[1].lower()
            if ext not in source_exts:
                continue
            full = os.path.join(root, f)
            try:
                with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                    content = fh.read(131072)
                lines = content.count("\n") + 1
                total_lines += lines
                comment_lines += len(comment_re.findall(content))
                todo_count += len(todo_re.findall(content))
                file_count += 1
            except Exception:
                continue

    if total_lines > 500 and file_count > 5:
        comment_ratio = comment_lines / total_lines
        if comment_ratio < 0.005:
            findings.append({
                "detail": f"В {file_count} файлах ({total_lines} строк) практически нет комментариев ({comment_lines} строк, {comment_ratio:.1%}) — код мог быть пропущен через чистилку",
                "severity": "medium",
            })
        if todo_count == 0 and total_lines > 2000:
            findings.append({
                "detail": f"Ни одного TODO/FIXME/HACK в {total_lines} строках кода — подозрительно чисто",
                "severity": "low",
            })

    return findings

def _check_missing_tests(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect missing test dirs when test frameworks are declared in build files."""
    findings: List[Dict[str, str]] = []

    test_framework_patterns = {
        "JUnit": re.compile(r'junit|org\.junit|jupiter', re.IGNORECASE),
        "Kotest": re.compile(r'kotest|io\.kotest', re.IGNORECASE),
        "TestNG": re.compile(r'testng', re.IGNORECASE),
        "Mockito": re.compile(r'mockito', re.IGNORECASE),
        "pytest": re.compile(r'pytest', re.IGNORECASE),
        "Jest": re.compile(r'jest', re.IGNORECASE),
        "Mocha": re.compile(r'mocha', re.IGNORECASE),
    }

    detected_frameworks: List[str] = []
    has_test_dir = False
    test_file_count = 0

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, dirs, files in _walk:
        for d in dirs:
            dl = d.lower()
            if dl in ("test", "tests", "__tests__", "spec", "specs",
                      "test-fixtures", "testfixtures", "androidtest"):
                has_test_dir = True
                # Count test files
                test_dir = os.path.join(root, d)
                for tr, _, tfiles in os.walk(test_dir):
                    test_file_count += len([
                        tf for tf in tfiles
                        if tf.lower().endswith((".java", ".kt", ".py", ".js", ".ts"))
                    ])

        for f in files:
            if f in ("build.gradle", "build.gradle.kts", "pom.xml",
                      "package.json", "requirements.txt", "setup.py",
                      "pyproject.toml", "Pipfile"):
                full = os.path.join(root, f)
                try:
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read(32768)
                    for fw_name, fw_pattern in test_framework_patterns.items():
                        if fw_pattern.search(content):
                            detected_frameworks.append(fw_name)
                except Exception:
                    continue

    # Also check src/test/
    _walk2 = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk2:
        rel = ftc.rel_path(root) if ftc else os.path.relpath(root, directory).replace("\\", "/")
        if "/src/test/" in rel or rel.startswith("src/test/"):
            has_test_dir = True
            test_file_count += len([
                f for f in files
                if f.lower().endswith((".java", ".kt", ".py", ".js", ".ts"))
            ])

    if detected_frameworks and not has_test_dir:
        frameworks = ", ".join(set(detected_frameworks))
        findings.append({
            "detail": f"Подключены тест-фреймворки ({frameworks}), но нет директории тестов — тесты удалены из архива",
            "severity": "high",
        })
    elif detected_frameworks and has_test_dir and test_file_count == 0:
        frameworks = ", ".join(set(detected_frameworks))
        findings.append({
            "detail": f"Подключены тест-фреймворки ({frameworks}), директория тестов есть, но пустая",
            "severity": "high",
        })

    return findings

def _check_stripped_binaries(directory: str, specials: List[str], ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect stripped .so/.dll binaries without debug symbols."""
    findings: List[Dict[str, str]] = []

    for sp in specials:
        full = os.path.join(directory, sp)
        ext = os.path.splitext(sp)[1].lower()
        try:
            if ext == ".so" or ".so." in sp:
                with open(full, "rb") as f:
                    magic = f.read(4)
                if magic != b"\x7fELF":
                    continue
                with open(full, "rb") as f:
                    data = f.read(65536)
                # Check for .debug_info section
                if b".debug_info" not in data and b".symtab" not in data:
                    findings.append({
                        "detail": f"{sp} — ELF без символов отладки (stripped)",
                        "severity": "low",
                    })
            elif ext in (".dll", ".exe"):
                with open(full, "rb") as f:
                    magic = f.read(2)
                if magic != b"MZ":
                    continue
                with open(full, "rb") as f:
                    data = f.read(65536)
                if b".pdb" not in data and b"RSDS" not in data:
                    findings.append({
                        "detail": f"{sp} — PE без PDB-отладки (stripped)",
                        "severity": "low",
                    })
        except Exception:
            continue

    return findings

def _check_autogenerated_ratio(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect high ratio of auto-generated code."""
    findings: List[Dict[str, str]] = []
    source_exts = {".java", ".kt", ".kts", ".py", ".js", ".ts", ".go", ".dart", ".scala"}

    total_files = 0
    generated_files = 0
    generated_markers = re.compile(
        r'(@Generated|@javax\.annotation\.Generated|'
        r'DO NOT EDIT|DO NOT MODIFY|AUTO.?GENERATED|'
        r'Generated by |This file is generated|'
        r'Automatically generated|generated code)',
        re.IGNORECASE
    )
    generated_names = re.compile(
        r'^(R\.java|BuildConfig\.java|.*Generated\..+|.*\.g\.dart|'
        r'.*_generated\.\w+|.*\.gen\.\w+|.*\.pb\.go|.*_pb2\.py)$',
        re.IGNORECASE
    )

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, _, files in _walk:
        if "__MACOSX" in root:
            continue
        for f in files:
            ext = os.path.splitext(f)[1].lower()
            if ext not in source_exts:
                continue
            total_files += 1
            full = os.path.join(root, f)

            if generated_names.match(f):
                generated_files += 1
                continue

            try:
                with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                    head = fh.read(1024)
                if generated_markers.search(head):
                    generated_files += 1
            except Exception:
                continue

    if total_files > 10 and generated_files > 0:
        ratio = generated_files / total_files
        if ratio > 0.5:
            findings.append({
                "detail": f"{generated_files}/{total_files} файлов ({ratio:.0%}) автосгенерированы — реальный код может быть скрыт за генерацией",
                "severity": "high",
            })
        elif ratio > 0.3:
            findings.append({
                "detail": f"{generated_files}/{total_files} файлов ({ratio:.0%}) автосгенерированы",
                "severity": "medium",
            })

    return findings

def _check_git_cleanup(directory: str, ftc: Optional[_FileTreeCache] = None) -> List[Dict[str, str]]:
    """Detect signs of git history removal."""
    findings: List[Dict[str, str]] = []

    has_gitignore = False
    has_git_dir = False

    _walk = ftc.walk() if ftc else os.walk(directory)
    for root, dirs, files in _walk:
        for f in files:
            if f == ".gitignore":
                has_gitignore = True
        for d in dirs:
            if d == ".git":
                has_git_dir = True
        depth = root.replace(directory, "").count(os.sep)
        if depth > 2:
            if not ftc:
                dirs.clear()

    if has_gitignore and not has_git_dir:
        findings.append({
            "detail": ".gitignore есть, но .git/ удалён — история коммитов (где могли быть секреты) недоступна",
            "severity": "medium",
        })

    return findings

def _check_archive_integrity(
    directory: str,
    classes: List[str],
    kotlins: List[str],
    specials: List[str],
    ext_counts: Dict[str, int],
) -> Dict[str, object]:
    """Run all integrity checks and return aggregated results with score."""

    ftc = _build_file_tree_cache(directory)

    all_checks = []

    # GROUP 1: Incomplete archive
    checks_group1 = [
        ("missing_imports", "Импорты ссылаются на отсутствующие классы/модули",
         lambda: _check_missing_imports(directory, ftc=ftc)),
        ("missing_modules", "Заявленные модули сборки отсутствуют",
         lambda: _check_module_declarations(directory, ftc=ftc)),
        ("stub_files", "Пустые файлы / заглушки",
         lambda: _check_stub_files(directory, ftc=ftc)),
        ("missing_packages", "Несоответствие package-деклараций и путей",
         lambda: _check_missing_packages(directory, ftc=ftc)),
        ("broken_inheritance", "Наследование от отсутствующих классов",
         lambda: _check_broken_inheritance(directory, ftc=ftc)),
        ("numbering_gaps", "Пропуски в нумерации директорий/модулей",
         lambda: _check_numbering_gaps(directory, ftc=ftc)),
        ("missing_layers", "Отсутствуют критичные архитектурные слои",
         lambda: _check_missing_layers(directory, ftc=ftc)),
        ("dead_config_refs", "Конфиги ссылаются на отсутствующие классы",
         lambda: _check_dead_config_refs(directory, ftc=ftc)),
        ("missing_manifests", "Нет файлов зависимостей (SCA/OSA невозможен)",
         lambda: _check_missing_manifests(directory, ext_counts, ftc=ftc)),
        ("missing_android_manifest", "Android-проект без AndroidManifest.xml",
         lambda: _check_missing_android_manifest(directory, ftc=ftc)),
    ]

    # GROUP 2: Substitution / concealment
    checks_group2 = [
        ("date_anomalies", "Аномалии дат файлов",
         lambda: _check_date_anomalies(directory, ftc=ftc)),
        ("size_anomalies", "Размерные аномалии (исходник-заглушка ↔ большой .class)",
         lambda: _check_size_anomalies(directory, classes, kotlins, ftc=ftc)),
        ("version_mismatches", "Несовпадение версий в build-файлах",
         lambda: _check_version_mismatches(directory, ftc=ftc)),
        ("nested_archives", "Вложенные/зашифрованные архивы",
         lambda: _check_nested_archives(directory, ftc=ftc)),
        ("renamed_extensions", "Файлы с подменёнными расширениями",
         lambda: _check_renamed_extensions(directory, ftc=ftc)),
        ("suspiciously_clean", "Подозрительно чистый код (нет комментариев/TODO)",
         lambda: _check_suspiciously_clean(directory, ftc=ftc)),
        ("missing_tests", "Тест-фреймворки подключены, но тесты удалены",
         lambda: _check_missing_tests(directory, ftc=ftc)),
        ("stripped_binaries", "Бинарники без символов отладки",
         lambda: _check_stripped_binaries(directory, specials, ftc=ftc)),
        ("autogenerated_ratio", "Высокая доля автосгенерированного кода",
         lambda: _check_autogenerated_ratio(directory, ftc=ftc)),
        ("git_cleanup", "Признаки удаления git-истории",
         lambda: _check_git_cleanup(directory, ftc=ftc)),
    ]

    findings_list: List[Dict[str, object]] = []
    critical_count = high_count = medium_count = low_count = 0

    for group_name, checks in [("incomplete", checks_group1), ("substitution", checks_group2)]:
        for check_id, title, check_fn in checks:
            try:
                results = check_fn()
                if not results:
                    continue

                details = [r["detail"] for r in results]
                # Use the highest severity from individual results
                severities = [r.get("severity", "medium") for r in results]
                sev_order = {"critical": 4, "high": 3, "medium": 2, "low": 1, "info": 0}
                max_sev = max(severities, key=lambda s: sev_order.get(s, 0))

                finding = {
                    "group": group_name,
                    "check_id": check_id,
                    "severity": max_sev,
                    "title": title,
                    "details": details,
                    "count": len(details),
                }
                findings_list.append(finding)

                # Count by check severity (not per-detail)
                if max_sev == "critical":
                    critical_count += 1
                elif max_sev == "high":
                    high_count += 1
                elif max_sev == "medium":
                    medium_count += 1
                elif max_sev == "low":
                    low_count += 1
            except Exception:
                continue

    # Calculate score: per-check penalty
    score = 100
    score -= min(critical_count * 20, 60)
    score -= min(high_count * 10, 40)
    score -= min(medium_count * 5, 20)
    score -= min(low_count * 2, 10)
    score = max(0, min(100, score))

    if score >= 80:
        verdict = "Архив выглядит полным"
    elif score >= 50:
        verdict = "Обнаружены признаки неполноты"
    elif score >= 20:
        verdict = "Архив значительно неполон"
    else:
        verdict = "Архив критически неполон / вероятна подмена"

    return {
        "findings": findings_list,
        "score": score,
        "verdict": verdict,
        "critical_count": critical_count,
        "high_count": high_count,
        "medium_count": medium_count,
        "low_count": low_count,
    }

