def _generate_appscreener_recommendations(
    directory: str,
    ext_counts: Dict[str, int],
    classes: List[str],
    kotlins: List[str],
    specials: List[str],
    integrity_result: Optional[Dict[str, object]] = None,
    kotlin_mapping: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """Determine AppScreener SAST mode for Java/Scala/Kotlin projects.

    AppScreener uses Java bytecode as intermediate representation for
    Java, Kotlin, and Scala.  Kotlin and Scala CANNOT be analyzed without
    .class files — the source-only mode works ONLY for Java.

    Three modes (exact AppScreener names):
      1. Анализ собранного проекта с .class файлами
      2. Анализ исходного кода со сборкой
      3. Анализ исходного кода (проект не будет собран, актуально только для Java)
    """
    rec: Dict[str, object] = {
        "sast_mode": "",
        "sast_reason": "",
        "kotlin_warnings": [],
    }

    java_count = ext_counts.get(".java", 0)
    kt_count = sum(ext_counts.get(e, 0) for e in (".kt", ".kts"))
    if kotlin_mapping is not None:
        kt_count = int(kotlin_mapping.get("total_kt", kt_count))
    scala_count = ext_counts.get(".scala", 0)
    class_count = ext_counts.get(".class", 0)

    has_java_src = java_count > 0
    has_kt_src = kt_count > 0
    has_scala_src = scala_count > 0
    has_class = class_count > 0
    has_jar = ext_counts.get(".jar", 0) > 0
    has_war = ext_counts.get(".war", 0) > 0

    src_count = java_count + kt_count + scala_count
    has_sources = has_java_src or has_kt_src or has_scala_src
    has_bytecode = has_class or has_jar or has_war

    # Check for build files
    has_build_gradle = False
    has_pom_xml = False
    for root, _, files in os.walk(directory):
        for f in files:
            fl = f.lower()
            if fl in ("build.gradle", "build.gradle.kts"):
                has_build_gradle = True
            elif fl == "pom.xml":
                has_pom_xml = True
        depth = root.replace(directory, "").count(os.sep)
        if depth > 3:
            break
    has_build_system = has_build_gradle or has_pom_xml

    # ── Kotlin/Scala .class coverage check ──
    # For Kotlin: check how many .kt have matching .class
    kt_class_coverage = None
    if has_kt_src and has_class and kotlin_mapping is None:
        # Legacy API callers retain the old heuristic. The current application
        # passes its single structural index and never repeats this scan.
        km = _check_kotlin_class_mapping(classes, kotlins)
        total_kt = km["total_kt"]
        matched_kt = km["total_matched"]
        kt_class_coverage = matched_kt / total_kt if total_kt > 0 else 0.0

        if kt_class_coverage < 1.0:
            unmatched = total_kt - matched_kt
            rec["kotlin_warnings"].append(
                f"{unmatched} из {total_kt} Kotlin-файлов (.kt) не имеют "
                f"соответствующих .class — AppScreener НЕ проанализирует эти файлы"
            )

    # ── Decision logic ──
    kotlin_warnings = rec["kotlin_warnings"]

    if has_sources and has_bytecode:
        # Have both source and bytecode
        rec["sast_mode"] = "Анализ собранного проекта с .class файлами"

        if has_kt_src and kt_class_coverage is not None:
            pct = int(kt_class_coverage * 100)
            if kt_class_coverage >= 0.9:
                rec["sast_reason"] = (
                    f"Исходники: {src_count} (Kotlin: {kt_count}), "
                    f"байткод: .class {class_count}. "
                    f"Покрытие Kotlin→.class: {pct}%. Оптимальный режим."
                )
            else:
                rec["sast_reason"] = (
                    f"Исходники: {src_count} (Kotlin: {kt_count}), "
                    f"байткод: .class {class_count}. "
                    f"⚠ Покрытие Kotlin→.class: {pct}% — часть Kotlin-кода "
                    f"НЕ будет проанализирована. Запросите полную сборку."
                )
        else:
            rec["sast_reason"] = (
                f"Исходники: {src_count}, байткод: .class {class_count}. "
                f"Оптимальный режим — максимальное покрытие анализа."
            )

    elif has_sources and not has_bytecode and has_build_system:
        # Sources + build system, no .class — AppScreener can build
        build_tool = "Gradle" if has_build_gradle else "Maven"
        rec["sast_mode"] = "Анализ исходного кода со сборкой"
        rec["sast_reason"] = (
            f"Исходники: {src_count} (Kotlin: {kt_count}, Java: {java_count}), "
            f"нет .class файлов. Найден {build_tool} — AppScreener соберёт проект."
        )
        if has_kt_src:
            kotlin_warnings.append(
                f"Kotlin ({kt_count} файлов) требует компиляции в .class для анализа. "
                f"AppScreener соберёт проект через {build_tool}, но рекомендуется "
                f"запросить у разработчика уже собранный проект (режим PREBUILD)."
            )

    elif has_java_src and not has_kt_src and not has_scala_src and not has_bytecode and not has_build_system:
        # Only Java, no build system, no .class — degraded mode OK for Java only
        rec["sast_mode"] = "Анализ исходного кода (проект не будет собран, актуально только для Java)"
        rec["sast_reason"] = (
            f"Только Java ({java_count} файлов), нет .class и нет системы сборки. "
            f"Будет использовано меньшее количество правил поиска уязвимостей."
        )

    elif (has_kt_src or has_scala_src) and not has_bytecode and not has_build_system:
        # Kotlin/Scala without .class AND without build system — BLOCKER
        langs = []
        if has_kt_src:
            langs.append(f"Kotlin ({kt_count})")
        if has_scala_src:
            langs.append(f"Scala ({scala_count})")
        if has_java_src:
            langs.append(f"Java ({java_count})")
        lang_str = ", ".join(langs)

        rec["sast_mode"] = "⚠ АНАЛИЗ НЕВОЗМОЖЕН"
        rec["sast_reason"] = (
            f"Обнаружены {lang_str}, но нет ни .class файлов, ни системы сборки "
            f"(build.gradle / pom.xml). Kotlin и Scala НЕЛЬЗЯ анализировать без "
            f"байткода — режим «без сборки» работает только для Java. "
            f"ЗАПРОСИТЕ у разработчика: собранный проект (.class) или файлы сборки."
        )
        kotlin_warnings.append(
            "БЛОКЕР: Kotlin/Scala невозможно проанализировать без .class файлов. "
            "Режим «Анализ исходного кода (проект не будет собран)» работает ТОЛЬКО для Java."
        )

    elif has_bytecode and not has_sources:
        # Only bytecode, no sources
        rec["sast_mode"] = "Анализ собранного проекта с .class файлами"
        rec["sast_reason"] = (
            f"Только байткод (.class: {class_count}), исходников нет. "
            f"Анализ возможен, но рекомендуется запросить исходники (.kt/.java) "
            f"для более полного покрытия."
        )

    else:
        rec["sast_mode"] = "Не определён"
        rec["sast_reason"] = "Не обнаружены файлы Java/Kotlin/Scala для SAST-анализа."

    if kotlin_mapping is not None and kotlins:
        from ..kotlin_coverage import coverage_for_mapping, coverage_text

        records = kotlin_mapping.get("records", [])
        counts = Counter(item.get("status") for item in records)
        checked = len(records) - counts["not_applicable"]
        rec["kotlin_warnings"] = []
        rec["sast_reason"] = (
            coverage_text(coverage_for_mapping(kotlin_mapping)) + " " +
            f"Структурное сопоставление Kotlin/JVM: подтверждено {counts['confirmed']} "
            f"из {checked}; частично {counts['partial']}; "
            f"не обнаружено {counts['missing']}; требуют проверки "
            f"{counts['probable'] + counts['ambiguous'] + counts['unverified']}. "
            "Это проверка комплектности, не процент покрытия SAST и не доказательство "
            "сборки из переданной версии исходников."
        )
        if counts["partial"] or counts["missing"]:
            rec["kotlin_warnings"].append(
                "Комплектность Kotlin-байткода не подтверждена для части исходников: "
                "см. объявления и реальные пути в разделе Kotlin ↔ .class."
            )
        if counts["probable"] + counts["ambiguous"] + counts["unverified"]:
            rec["kotlin_warnings"].append(
                "Есть предположительные, неоднозначные или непроверенные сопоставления Kotlin; "
                "они не считаются подтверждёнными."
            )
    return rec

